<?php

// The device a monitor (NMS) ticket is about, and the note when GLPI has no single such asset. Offline, synthetic names.
require __DIR__ . '/bootstrap.php';
require_once ITSM_ROOT . '/src/AssetLinker.php';

use GlpiPlugin\Itsmmigrator\AssetLinker as L;

$body = '<p>Title NMS - Pemberitahuan adanya insiden layanan SRV-A - 192.0.2.10 Termonitor Down Message Dear Team Detail Message: Device Down: No response Device: SRV-A 192.0.2.10 Category: Server Error Condition: Critical Generated at: 17 Jun 2026</p>';
check('device and address come from the body', L::parse('[FS#1] NMS - x', $body) === ['name' => 'SRV-A', 'ip' => '192.0.2.10']);
check('a name with spaces and dashes is kept whole', L::parse('NMS - x', 'AutoGenerated - NMS Device: SRV-B -Holistic- 192.0.2.11 Category: Server') === ['name' => 'SRV-B -Holistic-', 'ip' => '192.0.2.11']);
check('the subject is the fallback when the body has no Device line', L::parse('[FS#2] NMS - Pemberitahuan adanya insiden layanan Sw-core1 - 192.0.2.12 Termonitor Down', '<p>NMS alarm</p>') === ['name' => 'Sw-core1', 'ip' => '192.0.2.12']);
check('html entities and tags in the content are read through', L::parse('NMS', '<div>NMS&nbsp;Device:&nbsp;A&amp;B 192.0.2.13 Category: x</div>') !== null);
check('a ticket that is not from the monitor gives nothing', L::parse('Laptop rusak', '<p>Device: lama 192.0.2.14 Category: x</p>') === null);
check('a monitor ticket with no device gives nothing', L::parse('NMS - test', '<p>nothing here</p>') === null);

$n = L::note(['name' => 'SRV-A <b>', 'ip' => '192.0.2.10'], 0);
check('note: names the device, escaped, and says there is no asset', str_contains($n, L::MARK) && str_contains($n, 'SRV-A &lt;b&gt;') && str_contains($n, 'no asset with that name exists in GLPI'));
check('note: more than one asset is said so', str_contains(L::note(['name' => 'X', 'ip' => '192.0.2.1'], 2), 'more than one asset has that name'));

$src = (string) file_get_contents(ITSM_ROOT . '/src/AssetLinker.php');
$tw  = (string) file_get_contents(ITSM_ROOT . '/src/Writer/TicketWriter.php');
check('never creates an asset: only reads asset tables and adds the ticket link', !str_contains($src, '->add(["name"') && substr_count($src, '->add(') === 2 && str_contains($src, '\Item_Ticket'));
check('the writer links before finalize and a failure there never fails the ticket', strpos($tw, '$this->linkAsset($ticketId, $ctx)') < strpos($tw, '$this->finalize($t, $children, $ticketId, $ctx)') && str_contains($tw, 'asset link for ticket'));
check('custom assets (Wireless, Storage, Security...) share one table: each definition is searched only for its own rows', str_contains($src, "\$where['assets_assetdefinitions_id'] = \$type::getDefinition()->getID();") && str_contains($src, '\Glpi\Asset\Asset::class'));
check('a second run adds nothing: link kept, note added once', str_contains($src, "'glpi_items_tickets'") && str_contains($src, "'%' . self::MARK . '%'"));

$dev = ['name' => 'SRV-A <b>', 'ip' => '192.0.2.10'];
check('a stale "no asset" note and a "more than one" note are recognised, as stored (html escaped or not)', L::isStale(L::note($dev, 0)) && L::isStale(L::note($dev, 2)) && L::isStale(htmlspecialchars(L::note($dev, 0), ENT_QUOTES)));
check('the resolved note is not stale (a second link does not rewrite it) and it still carries the marker (no duplicate note is added)', !L::isStale(L::resolvedNote($dev)) && str_contains(L::resolvedNote($dev), L::MARK) && str_contains(L::resolvedNote($dev), 'now linked'));
check('the resolved note escapes the name', str_contains(L::resolvedNote($dev), 'SRV-A &lt;b&gt;'));
check('an unrelated note is never stale', !L::isStale('<p>Attachment not imported: x</p>') && !L::isStale('<p>Asset (monitor): x (1.2.3.4): now linked</p>'));
$src2 = (string) file_get_contents(ITSM_ROOT . '/src/AssetLinker.php');
check('a successful link (new or already there) replaces the stale note, never deletes it', str_contains($src2, 'self::resolveStaleNote($ticketId, $device)') && str_contains($src2, "\$DB->update('glpi_itilfollowups', ['content' => self::resolvedNote") && !str_contains($src2, "delete('glpi_itilfollowups'"));

done();
